# KIT-093: the transcriptomics count class, design validation and the whole-number count policy. The corpus and KIT-040's
# one-value fixtures are regenerated by KIT-040's generator and checked against KIT-040's recorded hashes before use.

trxDesignRoot <- function() normalizePath(testthat::test_path("..", ".."), mustWork = FALSE)

skipWithoutTrxGenerator <- function() {
    testthat::skip_if_not(file.exists(file.path(trxDesignRoot(), "tools/profiling/kit_omics_corpus.R")),
        "the KIT-040 generator and bindings are not shipped (R CMD check)")
}

trxDesignBindings <- function() jsonlite::read_json(file.path(trxDesignRoot(), "docs/qa/workflow-execution/kit/kit-040/bindings.json"))

trxDesignCorpus <- function(per_group, env = parent.frame()) {
    h <- new.env(parent = globalenv())
    sys.source(file.path(trxDesignRoot(), "tools/profiling/kit_omics_corpus.R"), h)
    dir <- withr::local_tempdir(.local_envir = env)
    h$writeKitTrxCorpus(dir, h$kitOmicsRecipe("trx_screen", per_group))
    list(dir = dir, tool = h)
}

trxDesignRead <- function(dir) {
    list(counts = vroom::vroom(file.path(dir, "counts.tsv"), show_col_types = FALSE),
        design = vroom::vroom(file.path(dir, "design_matrix.tab"), show_col_types = FALSE))
}

trxSampleColumns <- function(counts) setdiff(names(counts), c("GeneID", "GeneName"))

test_that("KIT-093: validateTrxDesign attaches labels by run ID in design-file order, with the declared levels", {
    design <- data.frame(Run = c("a", "b", "c", "d"), group = c("RPMI", "Sera", "RPMI", "Sera"), replicates = c(1, 1, 2, 2))
    columns <- c("d", "a", "c", "b")
    out <- validateTrxDesign(columns, design, c("RPMI", "Sera"), "Run", "group")
    expect_identical(out$design$Run, design$Run)
    expect_identical(out$group, factor(design$group, levels = c("RPMI", "Sera")))
    expect_identical(out$design$group, out$group)
    expect_identical(columns[out$count_index], design$Run)
    # The model-frame column is always `group`, and the sample column `Run`, whatever the design calls them.
    renamed <- stats::setNames(design, c("sample", "condition", "replicates"))
    alt <- validateTrxDesign(columns, renamed, c("RPMI", "Sera"), "sample", "condition")
    expect_identical(alt, out)
})

test_that("KIT-093: every design refusal is raised with its class, all under trx_design_invalid", {
    design <- data.frame(Run = c("a", "b", "c", "d"), group = c("RPMI", "Sera", "RPMI", "Sera"))
    columns <- design$Run
    levels <- c("RPMI", "Sera")
    refuse <- function(class, ...) {
        expect_error(validateTrxDesign(...), class = class)
        expect_error(validateTrxDesign(...), class = "trx_design_invalid")
    }
    refuse("trx_design_missing", columns, NULL, levels, "Run", "group")
    refuse("trx_design_missing", columns, design[0, ], levels, "Run", "group")
    refuse("trx_design_missing", columns, design, levels, "Sample", "group")
    refuse("trx_design_missing", columns, design, levels, "Run", "condition")
    refuse("trx_design_runs_extra", c(columns, "e"), design, levels, "Run", "group")
    refuse("trx_design_runs_missing", columns[-1], design, levels, "Run", "group")
    refuse("trx_design_runs_duplicated", c(columns, "a"), rbind(design, design[1, ]), levels, "Run", "group")
    refuse("trx_design_runs_duplicated", c(columns, "a"), design, levels, "Run", "group")
    unknown <- design; unknown$group[[2]] <- "LPS"
    refuse("trx_design_level_unknown", columns, unknown, levels, "Run", "group")
    unknown$group[[2]] <- NA
    refuse("trx_design_level_unknown", columns, unknown, levels, "Run", "group")
    empty <- design; empty$group <- "RPMI"
    refuse("trx_design_group_empty", columns, empty, levels, "Run", "group")
    three <- design; three$group[[4]] <- "LPS"
    refuse("trx_design_groups_unsupported", columns, three, c("RPMI", "Sera", "LPS"), "Run", "group")
})

test_that("KIT-093: validateTrxCounts refuses KIT-040's invalid fixtures and the in-test variants by class; whole doubles pass", {
    skipWithoutTrxGenerator()
    b <- trxDesignBindings()
    corpus <- trxDesignCorpus(3L)
    expect_identical(digest::digest(file = file.path(corpus$dir, "manifest.json"), algo = "sha256"), b$corpora$trx_edge_12$manifest_sha256)
    fixtures <- corpus$tool$writeKitTrxFixtures(corpus$dir, withr::local_tempdir())
    matrixOf <- function(dir) {
        counts <- vroom::vroom(file.path(dir, "counts.tsv"), show_col_types = FALSE)
        as.matrix(counts[, trxSampleColumns(counts)])
    }
    expected <- c(counts_na = "trx_counts_na", counts_negative = "trx_counts_negative", counts_fractional = "trx_counts_fractional")
    for (name in names(fixtures)) {
        expect_identical(digest::digest(file = file.path(fixtures[[name]], "counts.tsv"), algo = "sha256"), b$fixtures[[name]]$counts_sha256, info = name)
    }
    for (name in names(expected)) {
        expect_error(validateTrxCounts(matrixOf(fixtures[[name]])), class = expected[[name]])
        expect_error(validateTrxCounts(matrixOf(fixtures[[name]])), class = "trx_counts_invalid")
    }
    whole <- matrixOf(fixtures[["counts_whole_double"]])
    expect_type(whole, "double")
    expect_identical(validateTrxCounts(whole), whole)
    base <- matrixOf(corpus$dir)
    variant <- function(value, column = 1L) { x <- base; x[1L, column] <- value; x }
    expect_error(validateTrxCounts(variant(NaN)), class = "trx_counts_na")
    expect_error(validateTrxCounts(variant(Inf)), class = "trx_counts_nonfinite")
    expect_error(validateTrxCounts(variant(-Inf)), class = "trx_counts_nonfinite")
    zero <- base; zero[, 2L] <- 0
    expect_error(validateTrxCounts(zero), class = "trx_counts_zero_library")
    expect_error(validateTrxCounts(zero), class = "trx_counts_invalid")
    expect_identical(validateTrxCounts(base), base)
})

test_that("KIT-093: createTranscriptomicsAssayData builds a valid object from the screen corpus; validity runs both policies", {
    skipWithoutTrxGenerator()
    b <- trxDesignBindings()
    corpus <- trxDesignCorpus(6L)
    expect_identical(digest::digest(file = file.path(corpus$dir, "manifest.json"), algo = "sha256"), b$corpora$trx_screen$manifest_sha256)
    input <- trxDesignRead(corpus$dir)
    object <- createTranscriptomicsAssayData(list(counts = input$counts), input$design, c("RPMI", "Sera"))
    expect_s4_class(object, "TranscriptomicsAssayData")
    expect_true(methods::validObject(object))
    expect_identical(object@args$group_levels, c("RPMI", "Sera"))
    expect_identical(object@gene_id_column, "GeneID")
    expect_identical(object@annotation_id_column, "GeneName")
    inputs <- trxAssayInputs(object)
    expect_identical(colnames(inputs$counts), input$design$Run)
    expect_identical(levels(inputs$design$group), c("RPMI", "Sera"))
    # Validity refuses by class: a fractional count, and a run the design does not name.
    bad <- input$counts; bad[[trxSampleColumns(bad)[[1]]]][[1]] <- 0.5
    expect_error(createTranscriptomicsAssayData(list(counts = bad), input$design, c("RPMI", "Sera")), class = "trx_counts_fractional")
    expect_error(createTranscriptomicsAssayData(list(counts = input$counts), input$design[-1, ], c("RPMI", "Sera")), class = "trx_design_runs_extra")
    expect_error(createTranscriptomicsAssayData(list(a = input$counts, b = input$counts), input$design, c("RPMI", "Sera")), class = "trx_counts_invalid")
})

test_that("KIT-093: the TranscriptomicsAssayData declaration is accepted and read by the kit", {
    declaration <- workflowClassDeclaration("TranscriptomicsAssayData")
    expect_identical(validateWorkflowClassDeclaration(declaration), declaration)
    expect_identical(declaration$assay, "count_data")
    expect_identical(declaration$layout, "wide")
    expect_identical(declaration$design, "design_matrix")
    expect_identical(declaration$tables, "design_matrix")
    expect_identical(declaration$lists, "count_data")
    expect_identical(declaration$roles, c("gene_id_column", "annotation_id_column", "sample_id", "group_id", "technical_replicate_id"))
    expect_true("TranscriptomicsAssayData" %in% workflowDeclaredClassNames("assay"))
})
